fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut nums = [a, b, c];
    let max_val = *nums.iter().max().unwrap();

    // Calculate differences to max
    let diffs = nums.map(|x| max_val - x);

    // sum of differences
    let sum_diff: i8 = diffs.iter().sum();

    // count of odd differences, since increasing by 2 preserves parity,
    // and increasing two distinct integers by 1 flips parity of both,
    // the parity of all diffs must become 0
    let odd_count = diffs.iter().filter(|&&d| d % 2 != 0).count() as i8;

    // The minimum number of operations involves two parts:
    // 1. Make all differences even by pairing up odd differences (each such pair takes 1 operation)
    // 2. Then cover remaining difference by increments of 2 (each operation reducing 2 from difference)
    //
    // We can perform operations on one integer (+2) or two distinct (+1 each)
    // Using +1 on two distinct values reduces two differences by 1 simultaneously.
    //
    // To solve parity:
    //   Each +1/+1 operation reduces odd_count by 2
    //   So number of such ops needed = odd_count / 2
    //
    // After parity fixed, total increments left = sum_diff
    // Because each +1/+1 operation increases sum_diff by 2, and each +2 on one integer increases sum_diff by 2,
    // total operations = (sum_diff / 2) + (odd_count / 2)
    //
    // But since each operation adds 2 increments total (either +2 on one integer or +1 on two integers),
    // operations count = sum_diff/2 (counting increments of 2 collectively)
    // odd_count/2 is automatically included in that.
    //
    // But we have to be careful because sum_diff and odd_count may not line up evenly.
    // Actually, from solving similar problems, the formula for minimum operations is:
    //
    // operations = (sum_diff / 2) + (odd_count + 1) / 2
    //
    // This elegantly accounts for parity fixes first, then total increments.
    //
    // Note: integer division rounds down, so we add 1 before div to do ceiling.

    (sum_diff / 2) + ( (odd_count + 1) / 2 )
}